-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Unternehmensformen > AG
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung einer IT-AG auf das Gesellschaftsvermögen beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "Die AG haftet nur mit ihrem Vermögen"}, {"text": "Nein", "correct": false, "because": "Beschränkte Haftung ist ein Merkmal der AG"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IT-AG ein Mindestkapital von 50.000 Euro einbringen?', 2, '[{"text": "Ja", "correct": true, "because": "Das Mindestkapital einer AG beträgt 50.000 Euro"}, {"text": "Nein", "correct": false, "because": "Mindestkapital ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-AG Aktien an der Börse handeln?', 2, '[{"text": "Ja", "correct": true, "because": "AGs können börsennotiert sein"}, {"text": "Nein", "correct": false, "because": "Börsenhandel ist für AGs möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IT-AG einen Aufsichtsrat haben?', 2, '[{"text": "Ja", "correct": true, "because": "Ein Aufsichtsrat ist bei AGs gesetzlich vorgeschrieben"}, {"text": "Nein", "correct": false, "because": "Aufsichtsrat ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die AG als Unternehmensform für kleine IT-Startups typisch?', 2, '[{"text": "Nein", "correct": true, "because": "AGs sind für größere Unternehmen geeignet"}, {"text": "Ja", "correct": false, "because": "Startups wählen oft GmbH oder UG"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal einer IT-AG?', 2, '[{"text": "Beschränkte Haftung", "correct": true, "because": "Haftung ist auf das Gesellschaftsvermögen begrenzt"}, {"text": "Persönliche Haftung", "correct": false, "because": "Das gilt für Einzelunternehmen"}, {"text": "Keine Kapitalanforderung", "correct": false, "because": "Mindestkapital ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mindestkapital muss eine IT-AG aufbringen?', 3, '[{"text": "50.000 Euro", "correct": true, "because": "Gesetzlich vorgeschrieben für eine AG"}, {"text": "25.000 Euro", "correct": false, "because": "Das gilt für GmbH"}, {"text": "10.000 Euro", "correct": false, "because": "Zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt die Geschäfte einer IT-AG?', 3, '[{"text": "Vorstand", "correct": true, "because": "Der Vorstand leitet die AG"}, {"text": "Gesellschafter", "correct": false, "because": "Aktionäre sind Eigentümer, nicht Geschäftsführer"}, {"text": "Geschäftsführer", "correct": false, "because": "Geschäftsführer sind bei GmbH üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Gründung einer IT-AG?', 2, '[{"text": "Aktiengesetz (AktG)", "correct": true, "because": "Das AktG regelt die AG"}, {"text": "GmbH-Gesetz (GmbHG)", "correct": false, "because": "Gilt für GmbH"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil der AG als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Einfache Kapitalbeschaffung durch Aktien", "correct": true, "because": "AGs können Kapital an der Börse aufnehmen"}, {"text": "Geringe Gründungskosten", "correct": false, "because": "Gründungskosten sind hoch"}, {"text": "Keine Buchführungspflicht", "correct": false, "because": "AG ist buchführungspflichtig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine IT-AG?', 4, '[{"text": "Beschränkte Haftung", "correct": true, "because": "Haftung auf Gesellschaftsvermögen begrenzt"}, {"text": "Mindestkapital von 50.000 Euro", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Persönliche Haftung der Aktionäre", "correct": false, "because": "Nicht bei AG"}, {"text": "Vorstand und Aufsichtsrat", "correct": true, "because": "Pflichtorgane der AG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die AG als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Kapitalaufnahme durch Aktien", "correct": true, "because": "AG kann Aktien ausgeben"}, {"text": "Haftungsbeschränkung", "correct": true, "because": "Schützt Privatvermögen"}, {"text": "Keine Veröffentlichungspflicht", "correct": false, "because": "AG muss Abschlüsse veröffentlichen"}, {"text": "Hohe Flexibilität bei Finanzierung", "correct": true, "because": "Börsenhandel ermöglicht Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die AG als Unternehmensform für einen IT-Betrieb?', 4, '[{"text": "Hohe Gründungskosten", "correct": true, "because": "Mindestkapital und Formalitäten"}, {"text": "Komplexe Struktur", "correct": true, "because": "Vorstand und Aufsichtsrat erforderlich"}, {"text": "Persönliche Haftung", "correct": false, "because": "Nicht bei AG"}, {"text": "Veröffentlichungspflicht", "correct": true, "because": "Abschlüsse müssen offengelegt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Organe hat eine IT-AG?', 3, '[{"text": "Vorstand", "correct": true, "because": "Leitet die AG"}, {"text": "Aufsichtsrat", "correct": true, "because": "Kontrolliert den Vorstand"}, {"text": "Geschäftsführer", "correct": false, "because": "Gilt für GmbH"}, {"text": "Hauptversammlung", "correct": true, "because": "Versammlung der Aktionäre"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die AG von der GmbH für einen IT-Betrieb?', 3, '[{"text": "AG hat höheres Mindestkapital", "correct": true, "because": "50.000 Euro vs. 25.000 Euro"}, {"text": "AG hat Aufsichtsrat, GmbH nicht", "correct": true, "because": "Aufsichtsrat ist bei AG Pflicht"}, {"text": "GmbH kann Aktien ausgeben", "correct": false, "because": "Nur AG kann Aktien ausgeben"}, {"text": "AG hat strengere Veröffentlichungspflichten", "correct": true, "because": "AG muss mehr offenlegen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Haftung einer IT-AG ist beschränkt. b) Eine IT-AG benötigt kein Mindestkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine IT-AG kann Aktien an der Börse handeln. b) Eine IT-AG muss einen Aufsichtsrat haben.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Börsenhandel und Aufsichtsrat sind Merkmale"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Vorstand leitet eine IT-AG. b) Die AG ist für kleine IT-Startups ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vorstand ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine IT-AG hat hohe Gründungskosten. b) Eine IT-AG haftet mit dem Privatvermögen der Aktionäre.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IT-AG kann Kapital durch Aktien beschaffen. b) Eine IT-AG hat keine Veröffentlichungspflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktien ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

